{
  "name": "模块化 USB 控制面板手柄",
  "name_en": "Modular USB Control Console Handle",
  "manufacturer": "",
  "description": "一种通过 USB 连接的模块化实体控制面板，可包含按键、滑条和旋钮等输入部件，用于人工输入、设备控制和实验流程中的交互操作。",
  "description_en": "A USB-connected modular physical control console that can include buttons, sliders, and rotary controls, used for manual input, device control, and interactive operation in laboratory workflows.",
  "tag_hints": [
    "modular control surface",
    "USB HID/USB device",
    "buttons sliders knobs",
    "manual instrument control",
    "human-machine interface",
    "experimental user input"
  ],
  "actions": [
    {
      "action_name": "auto-write_messages",
      "description": "向控制面板写入消息数据。",
      "description_en": "Write message data to the control console."
    },
    {
      "action_name": "auto-bulkWrite",
      "description": "通过 USB 批量端点向设备发送数据。",
      "description_en": "Send data to the device through a USB bulk endpoint."
    },
    {
      "action_name": "auto-bulkRead",
      "description": "通过 USB 批量端点从设备读取数据。",
      "description_en": "Read data from the device through a USB bulk endpoint."
    },
    {
      "action_name": "auto-controlMsg",
      "description": "发送 USB 控制消息以执行设备控制或配置。",
      "description_en": "Send a USB control message for device control or configuration."
    },
    {
      "action_name": "auto-reset",
      "description": "复位设备连接或设备状态。",
      "description_en": "Reset the device connection or device state."
    },
    {
      "action_name": "auto-releaseInterface",
      "description": "释放设备的 USB 接口占用。",
      "description_en": "Release the claimed USB interface of the device."
    },
    {
      "action_name": "auto-components_connected",
      "description": "报告或处理已连接控制模块的状态。",
      "description_en": "Report or handle the status of connected control modules."
    },
    {
      "action_name": "auto-layout_changed",
      "description": "报告或处理控制模块布局发生变化。",
      "description_en": "Report or handle a change in the control module layout."
    },
    {
      "action_name": "auto-set_version_core",
      "description": "定义核心模块的版本信息。",
      "description_en": "Define the version information of the core module."
    },
    {
      "action_name": "auto-initialize_values",
      "description": "初始化控制部件的默认数值或状态。",
      "description_en": "Initialize default values or states of the control elements."
    },
    {
      "action_name": "auto-input_pressed",
      "description": "处理按键或输入部件被按下。",
      "description_en": "Handle a button or input element being pressed."
    },
    {
      "action_name": "auto-input_released",
      "description": "处理按键或输入部件被释放。",
      "description_en": "Handle a button or input element being released."
    },
    {
      "action_name": "auto-input_slide_up",
      "description": "处理滑条向上滑动输入。",
      "description_en": "Handle an upward slider movement input."
    },
    {
      "action_name": "auto-input_slide_down",
      "description": "处理滑条向下滑动输入。",
      "description_en": "Handle a downward slider movement input."
    },
    {
      "action_name": "auto-input_rotation_left",
      "description": "处理旋钮向左旋转输入。",
      "description_en": "Handle a leftward rotary input."
    },
    {
      "action_name": "auto-input_rotation_right",
      "description": "处理旋钮向右旋转输入。",
      "description_en": "Handle a rightward rotary input."
    }
  ]
}

